server {
    listen 443 ssl http2;
    server_name secure.example.com;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    location / {
        root /var/www/secure;
    }
}

server {
    listen 80;
    server_name www.example.com;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    location / {
        root /var/www/html;
    }
}

server {
    listen 443 ssl http2;
    server_name app.example.com;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:" always;
    location / {
        proxy_pass http://127.0.0.1:3000;
    }
}

server {
    listen 80;
    server_name www.example.com;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    location / {
        root /var/www/html;
    }
}

http {
    server_tokens off;
    server {
        listen 80;
        server_name www.example.com;
        location / {
            root /var/www/html;
        }
    }
}

server {
    listen 443 ssl http2;
    server_name privacy.example.com;
    add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
    location / {
        root /var/www/privacy;
    }
}

server {
    listen 80;
    server_name www.example.com;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    location / {
        root /var/www/html;
    }
}

server {
    listen 443 ssl http2;
    server_name preload.example.com;
    ssl_certificate /etc/ssl/certs/preload.crt;
    ssl_certificate_key /etc/ssl/private/preload.key;
    add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
    location / {
        root /var/www/preload;
    }
}

server {
    listen 80;
    server_name preload.example.com;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl http2;
    server_name isolated.example.com;
    add_header Cross-Origin-Opener-Policy "same-origin" always;
    add_header Cross-Origin-Resource-Policy "same-origin" always;
    location / {
        root /var/www/isolated;
    }
}

server {
    listen 443 ssl http2;
    server_name cdnapp.example.com;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' https://cdn.jsdelivr.net; style-src 'self' https://cdn.jsdelivr.net 'unsafe-inline'" always;
    location / {
        root /var/www/cdnapp;
    }
}

server {
    listen 80;
    server_name strip.example.com;
    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_hide_header X-Powered-By;
        proxy_hide_header Server;
    }
}

server {
    listen 80;
    server_name api.example.com;
    location /api/ {
        proxy_pass http://127.0.0.1:8080;
        add_header Cache-Control "no-store" always;
        add_header Pragma "no-cache" always;
    }
}

server {
    listen 80;
    server_name selective.example.com;
    location ~ \.html$ {
        root /var/www/selective;
        add_header X-Frame-Options "DENY" always;
    }
    location ~* \.(css|js|png|jpg|svg)$ {
        root /var/www/selective;
    }
}

server {
    listen 80;
    server_name report.example.com;
    add_header Content-Security-Policy-Report-Only "default-src 'self'; report-uri /csp-report" always;
    location /csp-report {
        proxy_pass http://127.0.0.1:9000;
    }
}

server {
    listen 80;
    server_name gone.example.com;
    return 444;
}

server {
    listen 80;
    server_name www.example.com;
    return 301 https://$host$request_uri;
}

server {
    listen 80;
    server_name legacy.example.com;
    add_header X-XSS-Protection "0" always;
    location / {
        root /var/www/legacy;
    }
}

server {
    listen 443 ssl http2;
    server_name analytics.example.com;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' https://www.googletagmanager.com; connect-src 'self' https://www.google-analytics.com" always;
    location / {
        root /var/www/analytics;
    }
}

server {
    listen 80;
    server_name embed.example.com;
    location = /checkout {
        add_header X-Frame-Options "DENY" always;
        proxy_pass http://127.0.0.1:8080;
    }
    location /widget {
        add_header Content-Security-Policy "frame-ancestors https://partner.example.com" always;
        proxy_pass http://127.0.0.1:8080;
    }
}

server {
    listen 443 ssl http2;
    server_name www.example.com;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy "geolocation=(), microphone=()" always;
    location / {
        root /var/www/html;
    }
}
